import{_ as e,o as a,c as d,ag as o}from"./chunks/framework.C5oN-8Wt.js";const m=JSON.parse('{"title":"复数增益器","description":"","frontmatter":{},"headers":[],"relativePath":"v0.2.0-alpha/modules/complex_gain/index.md","filePath":"v0.2.0-alpha/modules/complex_gain/index.md"}'),r={name:"v0.2.0-alpha/modules/complex_gain/index.md"};function l(i,t,c,h,n,p){return a(),d("div",null,[...t[0]||(t[0]=[o('<h1 id="复数增益器" tabindex="-1">复数增益器 <a class="header-anchor" href="#复数增益器" aria-label="Permalink to &quot;复数增益器&quot;">​</a></h1><p>适用：v0.2.0-alpha · GNU Radio 3.10.12.0<br> 模块类型：<code>complex_gain</code> · 模块定义版本：5</p><h2 id="是什么" tabindex="-1">是什么 <a class="header-anchor" href="#是什么" aria-label="Permalink to &quot;是什么&quot;">​</a></h2><p>将输入乘以一个固定复数系数，既能缩放幅度，也能旋转相位。系数的模决定缩放比例，辐角决定旋转角度，所有向量分量使用同一个系数。</p><h2 id="典型接线" tabindex="-1">典型接线 <a class="header-anchor" href="#典型接线" aria-label="Permalink to &quot;典型接线&quot;">​</a></h2><p><code>复数信号源.out → 复数增益器.in</code>。分别观察输入、输出的 I/Q 或星座图，使用相同范围比较轨迹大小和方向。</p><p>下表为内置默认参数下的端口。带路数、元素类型或 vlen 的模块会随参数改变流端口。</p><table tabindex="0"><thead><tr><th>方向</th><th>端口</th><th>数据类型</th><th>单位 / 形状</th></tr></thead><tbody><tr><td>输入</td><td><code>in</code>（输入）</td><td><code>complex_f64</code></td><td>归一化幅度；vlen=1</td></tr><tr><td>输出</td><td><code>out</code>（输出）</td><td><code>complex_f64</code></td><td>归一化幅度；vlen=1</td></tr></tbody></table><h2 id="参数怎么用" tabindex="-1">参数怎么用 <a class="header-anchor" href="#参数怎么用" aria-label="Permalink to &quot;参数怎么用&quot;">​</a></h2><p>系数由实部与虚部共同决定。只改变其中一项一般会同时改变模长和相位；若只想旋转而不缩放，应让复系数的模保持为 1。</p><p>例如乘以 <code>j</code> 会把 I/Q 平面中的向量旋转四分之一周。它不是只对 Q 增益，也不会给每个样本新增时间延迟。</p><p>内置默认值如下；本机设置可为<strong>新实例</strong>指定其他默认值，打开已有工程保留工程参数。</p><table tabindex="0"><thead><tr><th>参数</th><th>内置默认值</th><th>取值与约束</th><th>修改时机</th></tr></thead><tbody><tr><td>增益实部<br><code>gain_real</code></td><td><code>1</code></td><td>范围 -3.4028234663852886e+38 至 3.4028234663852886e+38</td><td>可在线应用</td></tr><tr><td>增益虚部<br><code>gain_imag</code></td><td><code>0</code></td><td>范围 -3.4028234663852886e+38 至 3.4028234663852886e+38</td><td>可在线应用</td></tr><tr><td>每个 item 的向量长度<br><code>vlen</code></td><td><code>1</code></td><td>范围 1 至 1024；Master 当前容量限制为 1–1024；采样率按 item 计。</td><td>重新准备</td></tr></tbody></table><h2 id="在线修改与重新准备" tabindex="-1">在线修改与重新准备 <a class="header-anchor" href="#在线修改与重新准备" aria-label="Permalink to &quot;在线修改与重新准备&quot;">​</a></h2><p>运行中可在线应用以下字段组；同组字段一起提交：</p><ul><li><code>gain_real</code>、<code>gain_imag</code></li></ul><p>其余计算字段需停止并重新准备。在线应用以该节点实际回执为准；编辑草稿本身不会改变已运行的图，旧缓存仍可能包含修改前的数据。</p><p>实部与虚部作为一组在线提交，以完整复系数的实际回执判断结果。改变向量长度需要重新准备；在线相位旋转不等于重新启动上游相位。</p><h2 id="下载与观察" tabindex="-1">下载与观察 <a class="header-anchor" href="#下载与观察" aria-label="Permalink to &quot;下载与观察&quot;">​</a></h2><h3 id="复数处理与-i-q-往返" tabindex="-1">复数处理与 I/Q 往返 <a class="header-anchor" href="#复数处理与-i-q-往返" aria-label="Permalink to &quot;复数处理与 I/Q 往返&quot;">​</a></h3><p><a href="../../../downloads/v0.2.0-alpha/complex-iq.cnsproj" download>下载 complex-iq.cnsproj</a></p><p>来源：PC 本地 GNU Radio 仿真。下载后打开工程，按 F5 运行；本次核验每例参考源运行 2048 item，工程不保存样本。</p><p>复数处理与 I/Q 往返</p><ul><li>观察复数旋转相量、乘 j 的相位变化及 I/Q 分解再合成；复数频谱保留正负频率。</li></ul><p>复数处理示例把信号源 1 乘以 <code>j</code>。输出满足 <code>I输出 = -Q输入</code>、<code>Q输出 = I输入</code>，模长保持不变。通过 I/Q 分量和轨迹方向同时核对，避免被自动刻度误导。</p><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><p><strong>乘了复数系数后幅度也变了？</strong> 计算系数的模，实部或虚部单独变化不一定保持单位模。</p><p><strong>负实系数会怎样？</strong> 它把相量翻转半周，并按绝对值缩放幅度。</p><h2 id="递进实验" tabindex="-1">递进实验 <a class="header-anchor" href="#递进实验" aria-label="Permalink to &quot;递进实验&quot;">​</a></h2><ul><li><a href="./../../learn/09-symbols/">09 码元、星座与判决</a></li></ul>',30)])])}const u=e(r,[["render",l]]);export{m as __pageData,u as default};
